public with sharing class Opportunities extends fflib_SObjectDomain {
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    public Opportunities(List<Opportunity> opportunities) {
        super(opportunities);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onAfterInsert() {
        if (records == null || records.isEmpty()) {
            return;
        }

        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : records) {
            Opportunity opportunity = (Opportunity) record;

            if (opportunity.Id != null && opportunity.StageName == CLOSED_WON_STAGE) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        callStartFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate() {
        if (records == null || records.isEmpty() || !Trigger.isUpdate) {
            return;
        }

        Map<Id, SObject> oldRecords = Trigger.oldMap;
        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : records) {
            Opportunity opportunity = (Opportunity) record;

            if (opportunity.Id == null || opportunity.StageName != CLOSED_WON_STAGE) {
                continue;
            }

            Opportunity oldOpportunity = (Opportunity) oldRecords.get(opportunity.Id);

            if (oldOpportunity != null && oldOpportunity.StageName != CLOSED_WON_STAGE) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        callStartFulfilment(qualifyingIds);
    }

    private void callStartFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilment =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

        fulfilment.startFulfilment(opportunityIds);
    }
}
